package com.neuroflow.common.exception;
import java.time.Instant;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;
@RestControllerAdvice
public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException ex){ List<String> details=ex.getBindingResult().getFieldErrors().stream().map(e->e.getField()+": "+e.getDefaultMessage()).toList(); return ResponseEntity.badRequest().body(new ApiError(Instant.now(),400,"Validation error","Dados inválidos",details)); } @ExceptionHandler(Exception.class) ResponseEntity<ApiError> generic(Exception ex){ return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(new ApiError(Instant.now(),500,"Internal server error","Erro interno inesperado",List.of())); } }
